import sys,numpy as np
from scipy import ndimage
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();o=r.get_obs(depth=True,video='none');c='over_shoulder_left_camera';im=o.last[c];d=o.last_depth[c];E=np.array(o.meta['cameras'][c]['extrinsic_cv']);K=np.array(o.meta['cameras'][c]['intrinsic_cv']);R,G,B=[im[:,:,i].astype(float) for i in range(3)];
for cond in [((R>150)&(G>120)&(B<80)&(G>1.3*B)),((R>120)&(G>100)&(B<90)&(G>1.5*B)),((R>160)&(G>130)&(B<60))]:
 m=cond.copy();m[:340]=False;m[420:]=False;m[:,:700]=False;m[:,850:]=False;lab,n=ndimage.label(m);sizes=np.bincount(lab.ravel());print('largest',sorted(sizes[1:],reverse=True)[:6]);
 for i in np.argsort(sizes[1:])[-5:]+1:
  yy,xx=np.nonzero(lab==i);z=d[yy,xx];ok=(z>0)&(z<4);xx=xx[ok];yy=yy[ok];z=z[ok]
  if len(z)<10:continue
  pc=np.stack([xx,yy,np.ones_like(xx)],1)@np.linalg.inv(K).T*z[:,None];w=(pc-E[:,3])@np.linalg.inv(E[:,:3]).T
  print(' ',sizes[i],(xx.min(),yy.min(),xx.max(),yy.max()),np.median(w,axis=0).round(3),np.percentile(w[:,2],[10,50,90]).round(3))
