from PIL import Image
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();o=r.get_obs(depth=True,video='none');
for c,im in o.last.items():Image.fromarray(im).save('/app/output/check_'+c+'.png');
print('tcp',o.meta['proprio']['now'][8:16]);print('left',o.meta['time_left_s'])
for c in ['over_shoulder_left_camera','egocentric_mirrored_camera']:
 im=o.last[c];d=o.last_depth[c];
 # print pixels with intense yellow in a coarse grid of candidates
 R,G,B=[im[:,:,i].astype(float) for i in range(3)];m=(R>160)&(G>130)&(B<100)&(G>1.2*B)
 yy,xx=np.nonzero(m);print(c,'yellow count',len(xx),'bbox',None if not len(xx) else (int(xx.min()),int(yy.min()),int(xx.max()),int(yy.max())))
 if len(xx):
  idx=np.argsort(yy);sel=idx[::max(1,len(idx)//20)];print('samples',[(int(xx[i]),int(yy[i]),round(float(d[yy[i],xx[i]]),3)) for i in sel[:20]])
